import json
import re
import sys
from pathlib import Path

import pdfplumber
import pandas as pd
from rapidfuzz import fuzz

PDF_PATH = Path('/root/participant_release_bundle.pdf')
REGISTRY_XLSX = Path('/root/participant_registry.xlsx')
AWARD_JSON = Path('/root/award_catalog.json')
VERSIONS_CSV = Path('/root/release_versions.csv')
OUTPUT_JSON = Path('/root/participant_release_flags.json')

def normalize(s: str) -> str:
    # lower, strip punctuation, collapse whitespace
    s = s.lower()
    s = re.sub(r"[\.,;:'\"\-]", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s

def parse_pdf():
    pages = []
    with pdfplumber.open(PDF_PATH) as pdf:
        for i, page in enumerate(pdf.pages):
            text = page.extract_text() or ""
            lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
            if not lines:
                continue
            if lines[0] != "Participant Release Request":
                continue
            # defaults
            data = {
                "page_number": i + 1,
                "packet_ref": None,
                "revision_no": None,
                "participant_name": None,
                "payment_token": None,
                "award_ref": None,
                "requested_amount": None,
            }
            for line in lines[1:]:
                if line.startswith('Packet Ref:'):
                    data['packet_ref'] = line.split(':', 1)[1].strip()
                elif line.startswith('Revision No:'):
                    try:
                        data['revision_no'] = int(line.split(':', 1)[1].strip())
                    except ValueError:
                        data['revision_no'] = None
                elif line.startswith('Participant'):
                    # could be "Participant:" or "Participant Name:"
                    part = line.split(':', 1)[1].strip()
                    data['participant_name'] = part
                elif line.startswith('Payment Token:'):
                    data['payment_token'] = line.split(':', 1)[1].strip()
                elif line.startswith('Award Ref:'):
                    val = line.split(':', 1)[1].strip()
                    data['award_ref'] = val if val else None
                elif line.startswith('Requested Amount:'):
                    amt = line.split(':', 1)[1].strip()
                    amt = amt.replace('$', '').replace(',', '')
                    try:
                        data['requested_amount'] = float(amt)
                    except ValueError:
                        data['requested_amount'] = None
            # Ensure required fields exist
            if data['packet_ref'] is not None and data['revision_no'] is not None:
                pages.append(data)
    return pages

def deduplicate(pages):
    # group by packet_ref
    grouped = {}
    for p in pages:
        key = p['packet_ref']
        if key not in grouped:
            grouped[key] = []
        grouped[key].append(p)
    retained = []
    for key, items in grouped.items():
        # find max revision
        max_rev = max(item['revision_no'] for item in items)
        candidates = [it for it in items if it['revision_no'] == max_rev]
        # if tie, keep highest page_number
        chosen = max(candidates, key=lambda x: x['page_number'])
        retained.append(chosen)
    return retained

def load_registry():
    xl = pd.ExcelFile(REGISTRY_XLSX)
    participants_df = xl.parse('participants')
    aliases_df = xl.parse('aliases')
    # build code -> payment_token map
    token_by_code = dict(zip(participants_df['participant_code'], participants_df['payment_token']))
    # name by code (canonical)
    name_by_code = dict(zip(participants_df['participant_code'], participants_df['participant_name']))
    # alias mapping: code -> list of alias names
    alias_map = {}
    for _, row in aliases_df.iterrows():
        code = row['participant_code']
        alias = row['alias_name']
        alias_map.setdefault(code, []).append(alias)
    # Build lookup structures
    # normalized name -> code (if collisions, keep first)
    norm_to_code = {}
    for code, name in name_by_code.items():
        norm = normalize(name)
        norm_to_code[norm] = code
        for alias in alias_map.get(code, []):
            norm_to_code[normalize(alias)] = code
    # also keep full list for fuzzy matching
    all_names = []  # list of (code, original_name)
    for code, name in name_by_code.items():
        all_names.append((code, name))
        for alias in alias_map.get(code, []):
            all_names.append((code, alias))
    return token_by_code, name_by_code, alias_map, norm_to_code, all_names

def load_awards():
    with open(AWARD_JSON) as f:
        data = json.load(f)
    awards = {}
    for sponsor in data.get('sponsors', []):
        for program in sponsor.get('programs', []):
            for aw in program.get('awards', []):
                if aw.get('status') != 'active':
                    continue
                ref = aw.get('award_ref')
                awards[ref] = {
                    'approved_amount': float(aw.get('approved_amount')),
                    'participant_code': aw.get('participant_code')
                }
    return awards

def load_version_overrides():
    df = pd.read_csv(VERSIONS_CSV, dtype=str)
    # Filter rows
    df = df[(df['approval_state'] == 'approved') &
            (df['version_amount'].notna()) & (df['version_amount'] != '') &
            (df['participant_code'].notna()) & (df['participant_code'] != '')]
    df['version_no'] = pd.to_numeric(df['version_no'], errors='coerce')
    df['version_amount'] = pd.to_numeric(df['version_amount'], errors='coerce')
    overrides = {}
    for ref, group in df.groupby('award_ref'):
        # keep highest version_no
        best = group.loc[group['version_no'].idxmax()]
        overrides[ref] = {
            'approved_amount': float(best['version_amount']),
            'participant_code': best['participant_code']
        }
    return overrides

def apply_overrides(awards, overrides):
    for ref, ov in overrides.items():
        if ref in awards:
            awards[ref] = ov
    return awards

def match_participant(name, all_names, norm_to_code):
    norm = normalize(name)
    # exact normalized match first
    if norm in norm_to_code:
        return norm_to_code[norm]
    # fuzzy match using rapidfuzz
    best_score = 0
    best_code = None
    for code, cand in all_names:
        score = fuzz.ratio(normalize(cand), norm)
        if score > best_score:
            best_score = score
            best_code = code
    if best_score >= 85:
        return best_code
    return None

def main():
    pages = parse_pdf()
    retained = deduplicate(pages)
    token_by_code, name_by_code, alias_map, norm_to_code, all_names = load_registry()
    awards = load_awards()
    overrides = load_version_overrides()
    awards = apply_overrides(awards, overrides)
    flagged = []
    for p in retained:
        reason = None
        # 1. Unknown Participant
        matched_code = match_participant(p['participant_name'], all_names, norm_to_code)
        if not matched_code:
            reason = 'Unknown Participant'
        else:
            # 2. Account Mismatch
            expected_token = token_by_code.get(matched_code)
            if expected_token != p['payment_token']:
                reason = 'Account Mismatch'
            else:
                # 3. Invalid Award Ref
                award_ref = p['award_ref']
                if not award_ref or award_ref not in awards:
                    reason = 'Invalid Award Ref'
                else:
                    award = awards[award_ref]
                    # 4. Amount Mismatch
                    if abs(p['requested_amount'] - award['approved_amount']) > 0.01:
                        reason = 'Amount Mismatch'
                    else:
                        # 5. Participant Mismatch
                        if award['participant_code'] != matched_code:
                            reason = 'Participant Mismatch'
        if reason:
            flagged.append({
                'request_page_number': p['page_number'],
                'participant_name': p['participant_name'],
                'requested_amount': p['requested_amount'],
                'payment_token': p['payment_token'],
                'award_ref': p['award_ref'],
                'reason': reason
            })
    # sort
    flagged.sort(key=lambda x: x['request_page_number'])
    # write output
    with open(OUTPUT_JSON, 'w') as f:
        json.dump(flagged, f, indent=2)
    # validation output
