        data = json.load(f)
    print(json.dumps(data, indent=2))
    print(f"Total flagged entries: {len(data)}")
    if data:
        pages_nums = [entry['request_page_number'] for entry in data]
        print('Flagged page numbers:', pages_nums)

if __name__ == '__main__':
    main()

